pub(crate) fn classify(ch: char) -> u16 {
    let cp = ch as u32;
    let i = RANGES.partition_point(|&(_, end, _)| end < cp);
    RANGES
        .get(i)
        .filter(|&&(start, _, _)| start <= cp)
        .map_or(0, |&(_, _, mask)| mask)
}

pub(crate) fn mapping(ch: char) -> Option<(&'static str, &'static str)> {
    MAPPINGS
        .binary_search_by_key(&(ch as u32), |&(cp, _, _)| cp)
        .ok()
        .map(|i| {
            let (_, upper, lower) = MAPPINGS[i];
            (upper, lower)
        })
}
